"use client";

import React, { useRef } from "react";
import { motion, useScroll, useSpring } from "motion/react";
import { Sparkles, BookOpen } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ScrollLinkedProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
}

export function ScrollLinked({
  title = "The Architecture of Motion",
  className,
  ...props
}: ScrollLinkedProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    container: containerRef,
  });

  const scaleX = useSpring(scrollYProgress, {
    stiffness: 120,
    damping: 30,
    restDelta: 0.001,
  });

  return (
    <div
      data-slot="scroll-linked"
      className={cn(
        "relative flex flex-col w-full max-w-xl mx-auto h-[480px] overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-950 shadow-2xl select-none",
        className
      )}
      {...props}
    >
      {/* Pinned Scroll Progress Indicator Bar */}
      <motion.div
        style={{ scaleX }}
        className="absolute top-0 left-0 right-0 h-1.5 origin-left bg-gradient-to-r from-pink-500 via-purple-500 to-indigo-500 z-20 shadow-xs"
      />

      {/* Header bar */}
      <div className="sticky top-0 z-10 flex items-center justify-between border-b border-neutral-100 dark:border-neutral-800/80 bg-white/90 dark:bg-neutral-900/90 px-6 py-3.5 backdrop-blur-md">
        <div className="flex items-center gap-2">
          <BookOpen className="h-4 w-4 text-pink-500" />
          <span className="text-xs font-bold text-neutral-900 dark:text-neutral-100">
            {title}
          </span>
        </div>
        <div className="flex items-center gap-1.5 text-[11px] font-mono text-neutral-500">
          <Sparkles className="h-3.5 w-3.5 text-purple-400" />
          <span>Scroll-Linked useScroll</span>
        </div>
      </div>

      {/* Scrollable Reader Article */}
      <div
        ref={containerRef}
        className="h-full overflow-y-auto p-8 space-y-6 text-neutral-700 dark:text-neutral-300 text-sm leading-relaxed"
      >
        <div>
          <span className="text-[10px] font-mono font-bold uppercase tracking-widest text-pink-500">
            Performance & Physics
          </span>
          <h3 className="text-2xl font-black tracking-tight text-neutral-900 dark:text-neutral-100 mt-1">
            Composited Web Animations
          </h3>
        </div>

        <p>
          Scroll-linked animations connect CSS styles directly to scroll position. In Motion, this is accomplished via the <code className="rounded bg-neutral-100 dark:bg-neutral-800 px-1.5 py-0.5 text-xs font-mono text-pink-500">useScroll</code> hook, computing normalized <code className="rounded bg-neutral-100 dark:bg-neutral-800 px-1.5 py-0.5 text-xs font-mono text-purple-500">scrollYProgress</code> values between 0 and 1.
        </p>

        <div className="rounded-2xl border border-neutral-100 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900 p-4 font-mono text-xs text-neutral-600 dark:text-neutral-400">
          const &#123; scrollYProgress &#125; = useScroll();<br />
          return &lt;motion.div style=&#123;&#123; scaleX: scrollYProgress, originX: 0 &#125;&#125; /&gt;
        </div>

        <h4 className="text-base font-bold text-neutral-900 dark:text-neutral-100 pt-2">
          Compositor-Driven Synchronization
        </h4>
        <p>
          By isolating transform operations to GPU composite layers, the browser updates scroll indicators seamlessly without triggering costly style recalculations, layout reflows, or repaint passes on the main thread.
        </p>

        <h4 className="text-base font-bold text-neutral-900 dark:text-neutral-100 pt-2">
          Responsive Layout Tracking
        </h4>
        <p>
          Whether bound to the root window viewport or custom nested overflow containers, progress tracking adapts instantaneously across all device viewports and screen densities.
        </p>

        <p className="pb-8 text-neutral-500 text-xs font-mono">
          End of article • Scroll progress reached 100%
        </p>
      </div>
    </div>
  );
}
